export default function TaskInterface({ task, act }) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const initial = !task || t.status === 'not_started';
  const busy = !!t.progress || ['working', 'created', 'submitting'].includes(t.status) || !!t.receipt;
  const disabled = initial || busy || typeof act !== 'function';
  const slots = Array.isArray(m.slots) ? m.slots : [];
  const checks = Array.isArray(t.checks) ? t.checks : [];
  const selectedId = intent.slotId;
  const selected = slots.find(s => s.id === selectedId);
  const targetDate = intent.targetDate || '2026-10-31';
  function text(value) {
    if (value === null || value === undefined || value === '') return 'Not supplied';
    if (typeof value === 'string' || typeof value === 'number') return String(value);
    if (typeof value === 'boolean') return value ? 'Yes' : 'No';
    try { return JSON.stringify(value); } catch (e) { return 'Unable to display value'; }
  }
  function parts(value) {
    if (typeof value !== 'string' || !/(Z|[+-]\d\d:\d\d)$/.test(value)) return null;
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return null;
    const result = {};
    new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'long', hour: '2-digit', hourCycle: 'h23' }).formatToParts(date).forEach(p => { result[p.type] = p.value; });
    return result;
  }
  function time(value) {
    if (!parts(value)) return 'Time unknown';
    return new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' }).format(new Date(value));
  }
  function fee(value) {
    if (typeof value !== 'number' || !Number.isFinite(value)) return 'Fee unknown';
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: m.currency || 'USD' }).format(value / 100);
  }
  function exclusions(s) {
    const why = [];
    const p = parts(s.startsAt);
    if (s.available !== true) why.push(s.available === false ? 'Unavailable' : 'Availability unknown');
    if (!p) why.push('Exact Pacific time unknown');
    else {
      const dateKey = p.year + '-' + p.month + '-' + p.day;
      if (p.weekday !== 'Saturday' || dateKey !== targetDate) why.push('Not the requested Saturday');
      if (Number(p.hour) >= 12) why.push('Not a morning appointment');
    }
    if (!s.technician) why.push('Technician unknown');
    else if (s.technician !== 'Maya Chen') why.push('Does not keep Maya Chen');
    if (typeof s.feeCents !== 'number' || !Number.isFinite(s.feeCents)) why.push('Additional fee unknown');
    else if (s.feeCents > Math.min(0, typeof intent.maxFeeCents === 'number' ? intent.maxFeeCents : 0)) why.push('Adds a fee');
    if (!s.id) why.push('Slot identifier missing');
    return why;
  }
  const fitting = slots.filter(s => exclusions(s).length === 0);
  const excluded = slots.filter(s => exclusions(s).length > 0);
  const original = m.originalBooking;
  const current = m.currentBooking;
  const conflictChecks = checks.filter(c => ['fail', 'failed', 'mismatch', 'conflict', 'error'].includes(c.status));
  const observedMismatch = !!selected && ((m.startsAt && m.startsAt !== selected.startsAt) || (m.technician && m.technician !== selected.technician) || (typeof m.feeCents === 'number' && m.feeCents !== selected.feeCents));
  const conflict = observedMismatch || conflictChecks.length > 0;
  const validSelection = !!selected && exclusions(selected).length === 0;
  const discovery = t.discovery || {};
  const screens = Array.isArray(discovery.screens) ? discovery.screens : [];
  const flows = Array.isArray(discovery.flows) ? discovery.flows : [];
  function booking(value) {
    if (!value) return <p className="generated-muted">Booking details not supplied.</p>;
    if (typeof value !== 'object') return <p>{text(value)}</p>;
    return <dl className="generated-details"><div><dt>Booking ID</dt><dd>{text(value.id || value.bookingId)}</dd></div><div><dt>Start</dt><dd>{time(value.startsAt)}</dd></div><div><dt>Technician</dt><dd>{text(value.technician)}</dd></div>{value.service && <div><dt>Service</dt><dd>{text(value.service)}</dd></div>}</dl>;
  }
  let status = initial ? 'Review the plan. This task has not started.' : 'Choose a matching time, then validate the source.';
  if (t.status && !initial) status = 'Task status: ' + t.status + '.';
  if (t.progress) status = 'In progress: ' + text(t.progress);
  if (t.receipt) status = 'A completion receipt is available in the host. Review its exact result and booking verification.';
  if (t.error) status = 'An error needs attention: ' + text(t.error);
  return <main className="generated-root">
    <header className="generated-header"><span className="generated-eyebrow">Linden Home · Synthetic service records</span><h1>Move your washer repair</h1><p className="generated-lead">Saturday morning. Keep Maya Chen. No added fee.</p><div className="generated-constraints"><span>Pacific time</span><span>Original booking protected until confirmation</span></div></header>
    <section className="generated-status" aria-label="Live task status" role="status" aria-live="polite">{status}</section>
    {initial ? <>
      <section className="generated-panel"><span className="generated-eyebrow">Task overview</span><h2>A new time, not a new technician</h2><p>Review matching availability, select a draft, and validate the exact source terms. The host provides Start this task and a separate approval step. Nothing is confirmed here.</p><ol className="generated-steps"><li>Keep the original repair booking while choosing.</li><li>Compare Saturday morning times in Pacific time.</li><li>Validate Maya Chen and no additional fee.</li><li>Approve exact terms in the host, then verify one active booking.</li></ol></section>
      <section className="generated-panel"><h2>What exploration reached</h2><div className="generated-evidence-row"><h3>Matching option</h3><p>Saturday, October 31 at 11 AM with Maya Chen was reached as a selected draft. The original booking remained unchanged. Confirmation was not verified.</p></div><div className="generated-evidence-row"><h3>Other observed alternatives</h3><p>The 9 AM option uses Luis Rivera, so it does not keep Maya. The 10 AM option keeps Maya but adds a fee. Neither fits your request.</p></div><p className="generated-muted">These are exploration findings, not current availability. Current times and amounts will come from the task after it starts.</p></section>
      <section className="generated-panel"><h2>Discovered screens and flows</h2>{screens.length ? screens.map((s, i) => <div className="generated-evidence-row" key={s.id || i}><h3>{text(s.name || s.title || 'Observed screen')}</h3><p>{text(s.description || 'Screen reached during exploration; completion is not established by this screen alone.')}</p></div>) : <p>Observed screen: Change your appointment | Linden Home. Appointment options were reached; confirmation was not executed.</p>}{flows.map((f, i) => <div className="generated-evidence-row" key={f.id || i}><h3>{text(f.name || f.title || 'Discovered flow')}</h3><p>Reached state: {text(f.reachedState || f.status || 'Not supplied')}</p><p>{text(f.description || 'Informational discovery; no execution is offered here.')}</p></div>)}</section>
    </> : <>
      <section className="generated-panel"><h2>Original booking</h2>{booking(original)}<p className="generated-muted">Choosing or validating a draft does not confirm a replacement. Exact approval is handled separately by the host.</p>{current && <div className="generated-divider"><h3>Currently observed booking</h3>{booking(current)}</div>}</section>
      <section className="generated-panel"><div className="generated-section-heading"><div><span className="generated-eyebrow">Choose a draft</span><h2>Matching Saturday times</h2></div><span className="generated-badge">Pacific time</span></div><p>Only available Saturday morning options with Maya Chen and no added fee can be chosen.</p>{fitting.length ? <fieldset className="generated-fieldset" disabled={disabled}><legend>Select your repair time</legend>{fitting.map((s, i) => <label className={'generated-option' + (selectedId === s.id ? ' generated-selected' : '')} key={s.id}><input type="radio" name="generated-repair-slot" checked={selectedId === s.id} onChange={() => act('choice', { slotId: s.id })} /><span><strong>{time(s.startsAt)}</strong><span className="generated-option-detail">{text(s.technician)} · Additional fee {fee(s.feeCents)}</span><span className="generated-option-detail">{selectedId === s.id ? 'Your selected draft' : 'Available matching option'}</span></span></label>)}</fieldset> : <p className="generated-notice">No matching options are currently supplied. Missing details or incompatible options block selection.</p>}{selectedId && !selected && <p className="generated-notice">Your selected slot ({text(selectedId)}) is not in the current availability data. Validate the source before proceeding.</p>}</section>
      <section className="generated-panel"><h2>Other observed options</h2><p className="generated-muted">Shown for comparison only. These do not meet every requirement.</p>{excluded.length ? excluded.map((s, i) => <div className="generated-excluded" key={s.id || i}><h3>{time(s.startsAt)}</h3><p>{text(s.technician)} · Additional fee {fee(s.feeCents)}</p><p className="generated-reason">Excluded: {exclusions(s).join('; ')}.</p></div>) : <p>{slots.length ? 'No other options were supplied.' : 'Availability has not been supplied yet.'}</p>}</section>
      <section className="generated-panel"><span className="generated-eyebrow">Review before approval</span><h2>Your choice and the source</h2><div className="generated-review-grid"><div><h3>Your requested draft</h3><p>{selected ? time(selected.startsAt) : 'No current slot selected'}</p><p>Keep Maya Chen · No added fee</p>{selected && <p>Draft additional fee: {fee(selected.feeCents)}</p>}</div><div><h3>Currently observed source terms</h3><p>{time(m.startsAt)}</p><p>Technician: {text(m.technician)}</p><p>Additional fee: {fee(m.feeCents)}</p><p>Source timezone: {text(m.timezone)}</p></div></div>{conflict && <div className="generated-notice" role="alert"><h3>Source conflict</h3><p>The observed source or checks do not match the requested terms. This is not a confirmed change. Restore your choices, then validate again.</p></div>}{checks.length > 0 && <div className="generated-checks"><h3>Source checks</h3>{checks.map((c, i) => <div className="generated-check" key={i}><strong>{text(c.label)}</strong><span>Status: {text(c.status)}</span><span>Requested: {text(c.expected)}</span><span>Observed: {text(c.observed)}</span></div>)}</div>}{t.validation && <div className="generated-divider"><h3>Validation report</h3><p className="generated-wrap">{text(t.validation)}</p></div>}<div className="generated-actions"><button type="button" disabled={disabled || !validSelection} onClick={() => act('check', { repair: false })}>Validate source</button>{conflict && <button className="generated-secondary" type="button" disabled={disabled || !validSelection} onClick={() => act('check', { repair: true })}>Restore my choices</button>}</div><p className="generated-muted">Validation is not confirmation. The host handles exact approval, completion, and verification that only one active booking remains.</p></section>
    </>}
    <footer className="generated-footer">Sandbox only · No production access · Unknown details stay visible</footer>
  </main>;
}
